}
const activeSessionCount=computed(()=>packages.value.reduce((sum,pkg)=>sum+(pkg.sessions||[]).filter(item=>item.status==='active').length,0));
const evidenceSources=computed(()=>{const rows=[];for(const cluster of clusterWorkspaces.value){if(session.value?.environment?.clusterId&&cluster.id!==session.value.environment.clusterId)continue;if(evidenceDraft.kind==='test-run'){for(const run of cluster.testRuns||[])if(run.status!=='running'&&packageDate(run.finishedAt)!=='Not recorded')rows.push({key:run.id,sourceId:run.id,clusterId:cluster.id,name:run.name||'Test Lab result',hint:`${clusterDisplayName(cluster.id)} · ${run.status} · ${packageDate(run.startedAt)}`});}else if(evidenceDraft.kind==='cache-snapshot'){for(const snapshot of cluster.snapshots||[])rows.push({key:`${snapshot.workspace}:${snapshot.id}`,sourceId:snapshot.id,workspaceId:snapshot.workspace,clusterId:cluster.id,name:snapshot.name||'Cache snapshot',hint:`${clusterDisplayName(cluster.id)} · ${packageDate(snapshot.createdAt)} · ${packageBytes(snapshot.bytes)}`});}}return rows;});
const sourceKey=ref('');
const sessionEvidence=computed(()=>session.value?.evidence||[]);

const findingOptions=computed(()=>session.value?.purpose==='reproduction'?[{id:'inconclusive',label:'Inconclusive'},{id:'reproduced',label:'Issue reproduced'},{id:'not-reproduced',label:'Issue not reproduced'}]:session.value?.purpose==='validation'?[{id:'inconclusive',label:'Inconclusive'},{id:'validated',label:'Fix validated'},{id:'not-validated',label:'Fix not validated'}]:[{id:'inconclusive',label:'Exploration recorded'},{id:'reproduced',label:'Issue reproduced'},{id:'not-reproduced',label:'Issue not reproduced'},{id:'validated',label:'Fix validated'},{id:'not-validated',label:'Fix not validated'}]);
const formatFinding=value=>({'reproduced':'Issue reproduced','not-reproduced':'Not reproduced','validated':'Fix validated','not-validated':'Not validated','inconclusive':'Inconclusive'}[value]||'Inconclusive');
