async function readEvidence(item){await perform('read-evidence',async()=>{const result=await request('read-evidence',{id:current.value.id,sessionId:session.value.id,sourceId:item.id});evidencePreview.value={id:item.id,...result,truncated:result.text.length>400000,text:result.text.slice(0,400000)};});}
