function syncSummary(){testPackageSummaries.value=packages.value.map(pkg=>({id:pkg.id,title:pkg.title,status:pkg.status,issueUrl:pkg.issueUrl,fixUrl:pkg.fixUrl,fixTitle:pkg.fixTitle,updatedAt:pkg.updatedAt,sessions:pkg.sessions||[],cases:pkg.cases||[]}));}
function install(pkg,{resetDraft=false}={}){const index=packages.value.findIndex(item=>item.id===pkg.id);if(index<0)packages.value.unshift(pkg);else packages.value.splice(index,1,pkg);if(resetDraft||!drafts[pkg.id])drafts[pkg.id]=editable(pkg);syncSummary();}
async function request(action,fields={}){const controller=new AbortController();controllers.add(controller);const timer=setTimeout(()=>controller.abort(),90000);try{const response=await apiFetch('/api/test-packages',action?{method:'POST',body:JSON.stringify({action,...fields}),signal:controller.signal}:{signal:controller.signal});if(!response.ok){const failure=new Error(await response.text());failure.status=response.status;throw failure;}return await response.json();}catch(err){if(err.name==='AbortError')throw new Error('This request took too long. Your saved package is still available. Refresh before retrying a change.');throw err;}finally{clearTimeout(timer);controllers.delete(controller);}}
const writingStates=reactive({}),writingLoaded=reactive({}),writingBases=reactive({}),writingRecovered=reactive({}),heldObservations=reactive({});
const writingConflict=ref(null);
const queuedWriting=new Map();
const writingController=createPackageDraftController({request,
  onState:(id,state)=>{if(!disposed)writingStates[id]=state;},
  onSaved:(id,response)=>{
    if(disposed)return;
    if(!response.draft.plan)writingBases[id]=response.currentPlanFingerprint;
    staleDrafts[id]=!!response.planChanged;
    for(const conflict of response.observationConflicts||[]){
      const key=`${id}/${conflict.sessionId}/${conflict.caseId}`;
      if(!Object.hasOwn(observationDrafts,key))continue;
