    }
  }
});
const writingState=computed(()=>writingStates[selectedId.value]||{});
const writingLabel=computed(()=>{
  if(writingState.value.status==='error'||writingState.value.status==='conflict')return 'Draft recovery needs attention';
  if(writingState.value.hasPending)return 'Saving writing draft…';
  if(dirty.value||Object.keys(observationDrafts).some(key=>key.startsWith(`${selectedId.value}/`)))return 'Draft secured locally';
  return 'Saved locally';
});
function writingPayload(id){
  const pkg=packages.value.find(item=>item.id===id);
  const observations=(heldObservations[id]||[]).map(({sessionId,caseId,baseNotes,notes})=>({sessionId,caseId,baseNotes,notes}));
  for(const [key,notes] of Object.entries(observationDrafts)){
    if(!key.startsWith(`${id}/`))continue;
    const [,sessionId,caseId]=key.split('/');
    observations.push({sessionId,caseId,baseNotes:observationBases[key]||'',notes});
  }
  return {basePlanFingerprint:writingBases[id],plan:pkg&&drafts[id]&&changedPlan(editable(pkg),drafts[id])?packageCopy(drafts[id]):null,observations};
}
function applyWritingRecovery(id,response){
  const pkg=packages.value.find(item=>item.id===id);if(!pkg)return;
  for(const key of Object.keys(observationDrafts))if(key.startsWith(`${id}/`)){delete observationDrafts[key];delete observationBases[key];}
  drafts[id]=response.draft.plan?editable(response.draft.plan):editable(pkg);
  writingBases[id]=response.draft.plan?response.draft.basePlanFingerprint:response.currentPlanFingerprint;
  staleDrafts[id]=!!response.planChanged;
  heldObservations[id]=[];
  for(const item of response.draft.observations||[]){
    const saved=pkg.sessions?.find(session=>session.id===item.sessionId)?.results?.find(result=>result.caseId===item.caseId);
    const conflict=response.observationConflicts?.find(row=>row.sessionId===item.sessionId&&row.caseId===item.caseId);
    if(!conflict&&saved&&(saved.notes||'')===item.notes)continue;
    if(conflict){heldObservations[id].push({...item,reason:conflict.reason});continue;}
    const key=`${id}/${item.sessionId}/${item.caseId}`;
    observationDrafts[key]=item.notes;observationBases[key]=item.baseNotes;
  }
  writingRecovered[id]=packageDraftHasWriting(response.draft);
  writingLoaded[id]=true;
  queuedWriting.set(id,JSON.stringify(writingPayload(id)));
  if(selectedId.value===id)selectedCaseId.value=drafts[id].cases[0]?.id||'';
}
async function loadWriting(id,force=false){
  if(writingLoaded[id]&&!force)return;
  try{const response=await writingController.load(id,{force});if(!disposed)applyWritingRecovery(id,response);}
  catch(err){if(!disposed)error.value=`Writing recovery could not open: ${err.message}`;}
}
async function persistWriting(id){
  if(!writingLoaded[id])throw new Error('Wait for writing recovery before saving.');
  const payload=writingPayload(id);queuedWriting.set(id,JSON.stringify(payload));
  await writingController.write(id,payload);
}
async function reviewWriting(){
  const id=selectedId.value;
  await perform('review-draft',async()=>{
    const response=await request('draft-read',{id});
    writingConflict.value={id,local:packageCopy(writingPayload(id)),remote:response};
  });
}
async function resolveWriting(useLocal){
  const review=writingConflict.value;if(!review)return;
  if(JSON.stringify(writingPayload(review.id))!==JSON.stringify(review.local)){review.local=packageCopy(writingPayload(review.id));error.value='Your writing changed while the review was open. Review the updated copy before choosing.';return;}
  await perform('recover-draft',async()=>{
    const latest=await writingController.load(review.id,{force:true});
    if(latest.draft.revision!==review.remote.draft.revision){review.remote=latest;throw new Error('The recovered draft changed again. Review the latest saved writing before choosing.');}
    const fresh=await request();const pkg=fresh.packages?.find(item=>item.id===review.id);
    if(!pkg)throw new Error('This package was removed in another view. Copy your writing before leaving.');
    install(pkg);
    if(useLocal){
      const local=review.local;
      const conflicts=(local.observations||[]).filter(item=>{
        const active=pkg.sessions?.find(session=>session.id===item.sessionId);
        const result=active?.results?.find(result=>result.caseId===item.caseId);
        return !active||active.status!=='active'||!result||(result.notes||'')!==item.baseNotes;
      }).map(item=>({sessionId:item.sessionId,caseId:item.caseId,reason:'The saved session or observation changed. This recovered text is kept separately.'}));
      applyWritingRecovery(review.id,{...latest,draft:{...latest.draft,...local},planChanged:!!local.plan&&local.basePlanFingerprint!==latest.currentPlanFingerprint,observationConflicts:conflicts});
    }else applyWritingRecovery(review.id,latest);
    await persistWriting(review.id);writingConflict.value=null;notice.value='Writing recovery updated. Save plan or save observations when ready.';
  });
}
async function keepPlanDraft(){
  const id=selectedId.value;
  await perform('keep-draft',async()=>{
    const records=await request();const pkg=records.packages?.find(item=>item.id===id);
    if(!pkg)throw new Error('This package was removed. Copy your writing before leaving.');
    const response=await request('draft-read',{id});
    install(pkg);writingBases[id]=response.currentPlanFingerprint;staleDrafts[id]=false;
    await persistWriting(id);
  });
}
watch(()=>JSON.stringify(Object.keys(drafts).filter(id=>writingLoaded[id]&&packages.value.some(pkg=>pkg.id===id)).map(id=>[id,writingPayload(id)])),()=>{
  for(const id of Object.keys(drafts)){
    if(!writingLoaded[id]||!packages.value.some(pkg=>pkg.id===id))continue;
    const payload=writingPayload(id),text=JSON.stringify(payload);
    if(queuedWriting.get(id)===text)continue;
    queuedWriting.set(id,text);writingController.queue(id,payload);
  }
});
function recoverableObservation(item){return sessions.value.some(session=>session.id===item.sessionId&&session.status==='active'&&session.cases.some(c=>c.id===item.caseId));}
async function useRecoveredObservation(item){
  const id=current.value.id;
  await perform('recover-observation',async()=>{
    const records=await request(),pkg=records.packages?.find(pkg=>pkg.id===id);
    const session=pkg?.sessions?.find(session=>session.id===item.sessionId);
    const result=session?.results?.find(result=>result.caseId===item.caseId);
