    notice.value='Recovered text is ready to review. Save the observation when you are ready.';
  });
}
function flushWritingOnHide(){if(document.visibilityState==='hidden')for(const id of Object.keys(writingStates))if(writingStates[id].hasPending)writingController.flush(id).catch(()=>{});}
async function perform(label,fn){if(pending.value)return false;pending.value=label;error.value='';notice.value='';try{await fn();return true;}catch(err){if(!disposed)error.value=err.message;return false;}finally{pending.value='';}}

async function saveOrganization(library){await perform('organize',async()=>{const result=await request('library-save',{library});packageLibrary.value=result.library;notice.value='Library organization saved.';});}
function prepareBulkExport(bucketId){bulkExport.value={bucketId,includeNotes:false,includeEvidence:false,library:packageCopy(packageLibrary.value)};}
async function exportOrganization(){const options={...bulkExport.value};await perform('bulk-export',async()=>{const result=await request('library-export',{...options,revision:options.library.revision});notice.value=`Exported ${result.packages} packages to Downloads: ${result.filename}`;bulkExport.value=null;});}
async function runCaseAutomation(caseId){await perform('prepare-automation',async()=>{const result=await request('automation-prepare',{id:current.value.id,sessionId:session.value.id,caseId});testWorkspaceIntent.value={packageAutomation:result};setActivePanelTab('tests');});}

async function refresh(){
  await perform('refresh',async()=>{
    const result=await request(),previous=packages.value;
    packages.value=result.packages||[];packageLibrary.value=result.library;
    for(const pkg of packages.value){
      const old=previous.find(item=>item.id===pkg.id);
      const hadChanges=old&&drafts[pkg.id]&&changedPlan(editable(old),drafts[pkg.id]);
      if(hadChanges){
        if(changedPlan(editable(old),editable(pkg))){staleDrafts[pkg.id]=true;notice.value='A newer saved plan was found. Your writing is preserved; review it before saving.';}
      }else if(drafts[pkg.id]){
        drafts[pkg.id]=editable(pkg);
        if(result.planFingerprints?.[pkg.id])writingBases[pkg.id]=result.planFingerprints[pkg.id];
      }
    }
    syncSummary();
    if(!selectedId.value&&packages.value.length)choosePackage(packages.value[0].id,true);
  });
  loading.value=false;consumeIntent();
}
function choosePackage(id,force=false){logCaptureOpen.value=false;if(pending.value&&!force)return;librarySharing.value='';selectedId.value=id;if(current.value&&!drafts[id])drafts[id]=editable(current.value);selectedCaseId.value=draft.value?.cases[0]?.id||'';selectedSessionId.value=sessions.value[0]?.id||'';sessionCaseId.value=session.value?.cases[0]?.id||'';view.value='overview';newOpen.value=false;startOpen.value=false;finishOpen.value=false;evidenceOpen.value=false;confirmation.value=null;error.value='';notice.value='';loadWriting(id);}
function openNew(issue={}){Object.assign(createDraft,{title:issue.title||'',issueUrl:issue.url||'',issueTitle:issue.title||'',fixUrl:'',fixTitle:'',summary:issue.body||''});librarySharing.value='';newOpen.value=true;nextTick(()=>newTitle.value?.focus({preventScroll:true}));}
async function createPackage(){await perform('create',async()=>{const result=await request('create',createDraft);install(result.package);packageLibrary.value.unfiled.push(result.package.id);query.value='';statusFilter.value='';clusterFilter.value='';choosePackage(result.package.id,true);notice.value='Package created. Start shaping the test plan.';view.value='plan';});}
async function savePlan(){const problem=packagePlanProblem(draft.value);if(problem){error.value=problem.message;if(problem.caseId){view.value='plan';selectedCaseId.value=problem.caseId;}return;}if(staleDrafts[selectedId.value]){error.value='Review the newer saved version before replacing it with this draft.';return;}await perform('save',async()=>{const id=current.value.id;await persistWriting(id);if(staleDrafts[id])throw new Error('The saved plan changed while recovering your writing. Review it before saving.');const result=await request('update',{id:current.value.id,revision:current.value.revision,...packageCopy(draft.value)});install(result.package,{resetDraft:true});writingBases[id]=result.currentPlanFingerprint;staleDrafts[id]=false;await persistWriting(id);writingRecovered[id]=false;notice.value='Plan saved. Existing sessions keep the cases they started with.';});}
function addCase(){const item={id:newPackageRecordID(),title:'',preconditions:'',expected:'',automation:'manual',automationUrl:'',selection:[],steps:[{id:newPackageRecordID(),instruction:'',expected:''}]};draft.value.cases.push(item);selectedCaseId.value=item.id;}
function updateCase(value){const index=draft.value.cases.findIndex(item=>item.id===value.id);if(index>=0)draft.value.cases.splice(index,1,value);}
function removeCase(caseId){draft.value.cases=draft.value.cases.filter(item=>item.id!==caseId);selectedCaseId.value=draft.value.cases[0]?.id||'';}
function prepareSession(){logCaptureOpen.value=false;if(dirty.value){error.value='Save the plan before starting a session. The session preserves that saved revision.';return false;}Object.assign(startDraft,{baselineSessionId:'',name:`${sessions.value.length?'Validation':'Reproduction'} ${sessions.value.length+1}`,purpose:sessions.value.length?'validation':'reproduction',clusterId:suggestedClusterId.value||clusterFilter.value||sessions.value[0]?.environment?.clusterId||'',url:'',rancherVersion:'',kubernetesVersion:'',images:'',configuration:'',fixUrl:current.value.fixUrl||'',fixTitle:current.value.fixTitle||'',fixCommit:''});fixLookup.start=null;fixLookupError.start='';startOpen.value=true;view.value='sessions';return true;}
function prepareValidation(baseline){
  if(pending.value||baseline?.status!=='completed')return;
  logCaptureOpen.value=false;finishOpen.value=false;evidenceOpen.value=false;
  Object.assign(startDraft,{baselineSessionId:baseline.id,name:`Validate · ${baseline.name}`.slice(0,200),purpose:'validation',clusterId:'',url:'',rancherVersion:'',kubernetesVersion:'',images:'',configuration:baseline.environment?.configuration||'',fixUrl:current.value.fixUrl||'',fixTitle:current.value.fixTitle||'',fixCommit:''});fixLookup.start=null;fixLookupError.start='';
  startOpen.value=true;view.value='sessions';
  nextTick(()=>document.getElementById('package-session-start')?.scrollIntoView({block:'start',behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'}));
}
function selectExecutionCase(id){sessionCaseId.value=id;nextTick(()=>document.getElementById('package-execution')?.focus({preventScroll:true}));}
function evidenceForCase({caseId}){sessionCaseId.value=caseId;prepareEvidence();nextTick(()=>document.getElementById('package-evidence-form')?.scrollIntoView({block:'center',behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'}));}
function environmentInput(){return {clusterId:startDraft.clusterId,url:startDraft.url,rancherVersion:startDraft.rancherVersion,kubernetesVersion:startDraft.kubernetesVersion,images:startDraft.images.split('\n').map(value=>value.trim()).filter(Boolean),configuration:startDraft.configuration};}
async function previewEnvironment(fresh=false){
  const sequence=++environmentSequence;
  if(!startOpen.value||!startDraft.clusterId){environmentPreview.value=null;environmentLoading.value=false;environmentError.value='';return;}
  if(!fresh&&environmentPreview.value?.clusterId!==startDraft.clusterId)environmentPreview.value=null;
  environmentLoading.value=true;environmentError.value='';
  const load=async()=>{try{const result=await request(fresh?'refresh-environment':'preview-environment',{environment:environmentInput()});if(sequence===environmentSequence&&!disposed)environmentPreview.value=result.environment;}catch(err){if(sequence===environmentSequence&&!disposed)environmentError.value=err.message;}finally{if(sequence===environmentSequence)environmentLoading.value=false;}};
  if(fresh)await perform('refresh-environment',load);else await load();
}
async function prepareLogCapture(caseId=sessionCaseId.value,stepId=''){
  if(pending.value)return;
  evidenceOpen.value=false;finishOpen.value=false;logCaseId.value=caseId;logStepId.value=stepId;logCaptureOpen.value=true;
  await nextTick();const form=document.getElementById('package-log-capture');form?.focus({preventScroll:true});form?.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});
}
async function captureLogs(fields){await perform('capture-logs',async()=>{await sessionMutation('capture-logs',fields);logCaptureOpen.value=false;notice.value='Log snapshot preserved with this session. Its pod identity, capture time, and requested window are recorded.';});}
async function startSession(){await perform('start',async()=>{const before=new Set((current.value.sessions||[]).map(item=>item.id));const environment={clusterId:startDraft.clusterId,url:startDraft.url,rancherVersion:startDraft.rancherVersion,kubernetesVersion:startDraft.kubernetesVersion,images:startDraft.images.split('\n').map(value=>value.trim()).filter(Boolean),configuration:startDraft.configuration};const fixUrl=startDraft.purpose==='validation'||startDraft.baselineSessionId?startDraft.fixUrl.trim():'';const result=await request('start-session',{id:current.value.id,revision:current.value.revision,name:startDraft.name,purpose:startDraft.purpose,baselineSessionId:startDraft.baselineSessionId,fixUrl,fixTitle:fixUrl?startDraft.fixTitle:'',fixCommit:fixUrl?startDraft.fixCommit.trim().toLowerCase():'',environment});install(result.package);selectedSessionId.value=result.package.sessions.find(item=>!before.has(item.id))?.id||result.package.sessions.at(-1)?.id;sessionCaseId.value=session.value?.cases?.[0]?.id||'';startOpen.value=false;notice.value='Session started. Steps are manual timestamps; no background collection has started.';});}
function chooseSession(id){if(pending.value)return;logCaptureOpen.value=false;selectedSessionId.value=id;sessionCaseId.value=session.value?.cases?.[0]?.id||'';startOpen.value=false;finishOpen.value=false;evidenceOpen.value=false;}
async function sessionMutation(action,fields={}){if(['case-result','finish-session'].includes(action))await persistWriting(current.value.id);if(action==='finish-session'&&heldObservations[current.value.id]?.some(item=>item.sessionId===session.value.id))throw new Error('Review the recovered observations for this session before preserving it.');if(action==='case-result'&&heldObservations[current.value.id]?.some(item=>item.sessionId===session.value.id&&item.caseId===fields.caseId))throw new Error('This case has a recovered observation conflict. Review or discard that separate recovery copy before replacing its saved result.');const result=await request(action,{id:current.value.id,revision:current.value.revision,sessionId:session.value.id,...fields});install(result.package);}
async function markStep(step,done){await perform('step',()=>sessionMutation('mark-step',{caseId:sessionCaseId.value,stepId:step.id,done}));}
async function outcome(value){await perform('outcome',async()=>{await sessionMutation('case-result',{caseId:sessionCaseId.value,outcome:value,notes:observation.value});delete observationDrafts[observationKey()];delete observationBases[observationKey()];await persistWriting(current.value.id);});}
async function saveObservation(){await perform('observation',async()=>{await sessionMutation('case-result',{caseId:sessionCaseId.value,outcome:caseResult.value?.outcome||'not-run',notes:observation.value});delete observationDrafts[observationKey()];delete observationBases[observationKey()];await persistWriting(current.value.id);notice.value='Observation saved with this case.';});}
function prepareFinish(){logCaptureOpen.value=false;finishDraft.finding='inconclusive';finishDraft.conclusion='';finishOpen.value=true;evidenceOpen.value=false;}
async function finishSession(){await perform('finish',async()=>{
  if(heldObservations[current.value.id]?.some(item=>item.sessionId===session.value.id))throw new Error('Review the recovered observations for this session before preserving it.');
  for(const item of session.value.results||[]){
    const key=`${selectedId.value}/${selectedSessionId.value}/${item.caseId}`;
    if(Object.hasOwn(observationDrafts,key)&&observationDrafts[key]!==item.notes)await sessionMutation('case-result',{caseId:item.caseId,outcome:item.outcome,notes:observationDrafts[key]});
    delete observationDrafts[key];delete observationBases[key];
  }
  await sessionMutation('finish-session',{finding:finishDraft.finding,conclusion:finishDraft.conclusion});
  await persistWriting(current.value.id);finishOpen.value=false;notice.value='Session preserved. Its cases, results, and evidence are now read-only.';
});}
function prepareEvidence(){logCaptureOpen.value=false;Object.assign(evidenceDraft,{kind:'test-run',sourceId:'',workspaceId:'',includeDatabase:false,description:'',name:'',caseId:sessionCaseId.value,stepId:''});sourceKey.value='';evidenceOpen.value=true;finishOpen.value=false;}
async function refreshEvidence(){await perform('refresh-evidence',async()=>{await refreshClusterWorkspaces({fresh:true});if(clusterWorkspaceError.value)throw new Error(clusterWorkspaceError.value);notice.value='Saved lab evidence refreshed.';});}
async function attachEvidence(){await perform('evidence',async()=>{const source=evidenceSources.value.find(item=>item.key===sourceKey.value);await sessionMutation('attach-evidence',{...evidenceDraft,sourceId:source?.sourceId||'',workspaceId:source?.workspaceId||''});evidenceOpen.value=false;notice.value='Evidence attached. Copied files stay with this package if the lab source is cleaned up.';});}
async function confirmAction(){const action=confirmation.value;if(!action)return;await perform('delete',async()=>{if(action.action==='remove-case'){removeCase(action.caseId);confirmation.value=null;return;}if(action.action==='discard-recovery'){heldObservations[current.value.id]=[];await persistWriting(current.value.id);confirmation.value=null;return;}if(action.action==='discard'){await writingController.flush(current.value.id);const records=await request();const saved=(records.packages||[]).find(item=>item.id===current.value.id);if(!saved)throw new Error('The saved package no longer exists. Export your draft text before leaving.');install(saved,{resetDraft:true});const response=await request('draft-read',{id:saved.id});writingBases[saved.id]=response.currentPlanFingerprint;staleDrafts[saved.id]=false;await persistWriting(saved.id);writingRecovered[saved.id]=false;confirmation.value=null;return;}const result=await request(action.action,{id:current.value.id,revision:current.value.revision,sessionId:action.sessionId,sourceId:action.sourceId,confirm:'confirm'});confirmation.value=null;if(action.action==='delete'){const removed=selectedId.value;writingController.forget(removed);delete writingStates[removed];delete writingLoaded[removed];delete writingBases[removed];delete writingRecovered[removed];delete heldObservations[removed];queuedWriting.delete(removed);packages.value=packages.value.filter(item=>item.id!==removed);packageLibrary.value.unfiled=packageLibrary.value.unfiled.filter(id=>id!==removed);for(const b of packageLibrary.value.buckets)b.packageIds=b.packageIds.filter(id=>id!==removed);delete drafts[removed];for(const key of Object.keys(observationDrafts))if(key.startsWith(`${removed}/`)){delete observationDrafts[key];delete observationBases[key];}selectedId.value='';syncSummary();if(packages.value[0])choosePackage(packages.value[0].id,true);}else{install(result.package);if(action.action==='delete-session'){for(const key of Object.keys(observationDrafts))if(key.startsWith(`${current.value.id}/${action.sessionId}/`)){delete observationDrafts[key];delete observationBases[key];}await persistWriting(current.value.id);selectedSessionId.value=sessions.value[0]?.id||'';sessionCaseId.value=session.value?.cases?.[0]?.id||'';}}notice.value='Removed from your local package library.';});}
function ask(action,fields={}){confirmation.value={action,id:current.value.id,caseId:selectedCaseId.value,...fields};}
async function openURL(url){if(!safePackageURL(url))return;await perform('open',async()=>{const response=await apiFetch('/api/open-url',{method:'POST',body:JSON.stringify({url})});if(!response.ok)throw new Error(await response.text());});}
function imported(pkg){install(pkg);if(!packageLibrary.value.unfiled.includes(pkg.id))packageLibrary.value.unfiled.push(pkg.id);query.value='';statusFilter.value='';clusterFilter.value='';librarySharing.value='';choosePackage(pkg.id);notice.value='Package imported as a new local copy. Nothing was run.';}
function consumeIntent(){if(loading.value||pending.value||activeTab.value!=='packages'||!testPackageIntent.value)return;const intent=testPackageIntent.value;testPackageIntent.value=null;clusterFilter.value=intent.create?'':intent.clusterId||'';suggestedClusterId.value=intent.clusterId||'';query.value='';statusFilter.value='';if(intent.create){openNew(intent.issue||{});return;}if(intent.packageId&&packages.value.some(item=>item.id===intent.packageId)){choosePackage(intent.packageId);if(intent.sessionId){selectedSessionId.value=intent.sessionId;sessionCaseId.value=session.value?.cases?.[0]?.id||'';view.value='sessions';}}}
watch([activeTab,testPackageIntent,pending],consumeIntent);
watch(activeTab,(tab)=>{if(tab==='packages'&&!loading.value&&!pending.value)refresh();});

watch([()=>JSON.stringify(environmentInput()),startOpen],()=>{
  ++environmentSequence;clearTimeout(environmentPreviewTimer);
  if(!startOpen.value||!startDraft.clusterId){previewEnvironment();return;}
  environmentLoading.value=true;environmentPreviewTimer=setTimeout(()=>previewEnvironment(),200);
});
watch(()=>evidenceDraft.kind,()=>{sourceKey.value='';evidenceDraft.includeDatabase=false;});
watch(()=>evidenceDraft.caseId,()=>{evidenceDraft.stepId='';});
function beforeUnload(event){if(Object.values(writingStates).some(state=>state.hasPending||state.status==='error'||state.status==='conflict')){event.preventDefault();event.returnValue='';}}
onMounted(()=>{window.addEventListener('beforeunload',beforeUnload);document.addEventListener('visibilitychange',flushWritingOnHide);refresh();});
onBeforeUnmount(()=>{disposed=true;writingController.dispose();document.removeEventListener('visibilitychange',flushWritingOnHide);clearTimeout(environmentPreviewTimer);for(const controller of controllers)controller.abort();window.removeEventListener('beforeunload',beforeUnload);});
</script>
<template>
<section class="test-packages" aria-label="Test Packages">
  <header class="tp-hero"><div><span class="tp-eyebrow"><Icon name="boxes"/>RANCHER RUNWAY / QA WORKSPACE</span><h2>Test Packages<span>.</span></h2><p>From the first reproduction to the final finding. Keep the whole story.</p></div><div class="tp-hero-counts"><span><strong>{{packages.length}}</strong> packages</span><span><strong>{{activeSessionCount}}</strong> active sessions</span></div></header>
  <div v-if="error" class="tp-notice tp-error" role="alert"><Icon name="signal"/><span>{{error}}</span><button type="button" aria-label="Dismiss error" @click="error=''"><Icon name="close"/></button></div>
  <div v-if="notice" class="tp-notice" role="status"><Icon name="check"/><span>{{notice}}</span><button type="button" aria-label="Dismiss message" @click="notice=''"><Icon name="close"/></button></div>
  <form v-if="bulkExport" class="tp-notice tp-bulk-export" @submit.prevent="exportOrganization"><div><strong>Export {{bulkExport.bucketId?(packageLibrary.buckets.find(b=>b.id===bulkExport.bucketId)?.name||'Unfiled'):'the whole library'}}</strong><p>Ordered ZIP with portable packages, Markdown reports, and a library index. Only saved work is included. Unzip to import individual packages.</p><label class="tp-check"><input v-model="bulkExport.includeNotes" type="checkbox" :disabled="!!pending"/>Include private package notes</label><label class="tp-check"><input v-model="bulkExport.includeEvidence" type="checkbox" :disabled="!!pending"/>Include copied logs and databases · review sensitive content before sharing</label><div class="tp-actions"><button type="submit" class="tp-primary" :disabled="!!pending">{{pending==='bulk-export'?'Exporting…':'Export to Downloads'}}</button><button type="button" :disabled="!!pending" @click="bulkExport=null">Cancel</button></div></div></form><div class="tp-workspace">
    <aside class="tp-library" aria-label="Package library"><div class="tp-library-top"><div><span class="tp-eyebrow">YOUR LIBRARY</span><button type="button" class="tp-icon-button" title="Refresh saved packages" aria-label="Refresh saved packages" :disabled="!!pending" @click="refresh"><Icon name="refresh"/></button></div><button type="button" class="tp-primary tp-new" :disabled="!!pending" @click="openNew()"><Icon name="plus"/>New test package</button><label class="tp-search"><Icon name="search"/><input v-model="query" type="search" aria-label="Find a test package" placeholder="Find a package or issue…"/></label><select v-model="statusFilter" aria-label="Filter packages by status"><option value="">Every status</option><option v-for="status in PACKAGE_STATUSES" :key="status.id" :value="status.id">{{status.label}}</option></select><button v-if="clusterFilter" type="button" class="tp-filter" @click="clusterFilter=''">{{clusterDisplayName(clusterFilter)}}<Icon name="close"/></button></div>
      <div class="tp-library-list"><p v-if="loading" class="tp-library-empty">Opening your library…</p><p v-if="!loading&&packages.length&&!filtered.length" class="tp-library-empty">No packages match this search or filter.</p><PackageLibrary v-if="!loading" :library="packageLibrary" :packages="packages" :visible="filtered" :selected-id="newOpen?'':selectedId" :busy="!!pending" @select="choosePackage" @save="saveOrganization" @export="prepareBulkExport"/></div><div class="tp-library-tools"><button type="button" class="tp-link" :disabled="!!pending" @click="librarySharing='bundle';newOpen=false"><Icon name="upload"/>Import a package</button><button type="button" class="tp-link" :disabled="!!pending" @click="librarySharing='archive';newOpen=false"><Icon name="lock"/>Open private archive</button></div><footer><Icon name="lock"/><span>Personal library · saved on this computer</span></footer>
    </aside>
    <main class="tp-main">
      <div v-if="librarySharing" class="tp-content"><button type="button" class="tp-link" @click="librarySharing=''"><Icon name="arrow-left"/>Back to package</button><Sharing :key="librarySharing" :initial-mode="librarySharing" @imported="imported"/></div><form v-else-if="newOpen" class="tp-create" @submit.prevent="createPackage"><div class="tp-create-emblem"><Icon name="boxes"/></div><span class="tp-eyebrow">MAKE ROOM FOR AN INVESTIGATION</span><h3>What are you working on?</h3><p>Start with a question. Cases and notes can take shape before an environment or fix is ready.</p><label>Package name<input ref="newTitle" v-model="createDraft.title" maxlength="200" required placeholder="Project visibility after a role change" :disabled="!!pending"/></label><label>GitHub issue <span>optional</span><input v-model="createDraft.issueUrl" @input="createDraft.issueTitle=''" type="url" placeholder="https://github.com/rancher/rancher/issues/…" :disabled="!!pending"/></label><label>Fix pull request <span>optional</span><input v-model="createDraft.fixUrl" type="url" placeholder="https://github.com/rancher/rancher/pull/…" :disabled="!!pending"/></label><label>{{createDraft.issueTitle?'Issue context · editable':'What should this establish?'}}<textarea v-model="createDraft.summary" rows="5" placeholder="Describe the issue, the expected behavior, and what you want to learn." :disabled="!!pending"/></label><div class="tp-actions"><button type="submit" class="tp-primary" :disabled="!!pending||!createDraft.title.trim()"><Icon name="plus"/>{{pending==='create'?'Creating…':'Create package'}}</button><button type="button" :disabled="!!pending" @click="newOpen=false">Cancel</button></div><p class="tp-hint">No tests run and no GitHub content changes when you create a package.</p></form>
      <div v-else-if="current&&!writingLoaded[current.id]" class="tp-content tp-empty" role="status"><Icon name="clock"/><h4>Opening your writing workspace…</h4><p>Checking for unfinished cases and observations.</p><button v-if="writingState.status==='error'" type="button" @click="loadWriting(current.id,true)">Retry draft recovery</button></div>
      <template v-else-if="current&&draft">
        <header class="tp-package-heading"><div><span class="tp-eyebrow">{{current.issueUrl?'ISSUE INVESTIGATION':'PERSONAL TEST PACKAGE'}}<span class="tp-status" :data-status="current.status">{{packageStatus(current.status)}}</span></span><h3>{{current.title}}</h3><button v-if="current.issueUrl" type="button" class="tp-link tp-issue" @click="openURL(current.issueUrl)">{{current.issueTitle||current.issueUrl}}<Icon name="external"/></button><p v-else class="tp-hint">Created {{packageDate(current.createdAt)}} · {{current.cases.length}} cases · {{sessions.length}} sessions</p><button v-if="current.fixUrl" type="button" class="tp-link tp-issue tp-fix" @click="openURL(current.fixUrl)"><Icon name="branch"/>Fix: {{current.fixTitle||current.fixUrl}}<Icon name="external"/></button></div><button type="button" class="tp-primary" :disabled="!!pending||!current.cases.length||dirty" :title="dirty?'Save the plan before starting a session':''" @click="prepareSession"><Icon name="play"/>Start session</button></header>
        <nav class="tp-view-nav" aria-label="Package sections"><button v-for="item in [{id:'overview',label:'Overview',icon:'compass'},{id:'plan',label:'Test plan',icon:'file'},{id:'sessions',label:'Sessions',icon:'clock'},{id:'share',label:'Report & share',icon:'upload'}]" :key="item.id" type="button" :aria-current="view===item.id?'page':undefined" :disabled="!!pending" @click="view=item.id"><Icon :name="item.icon"/>{{item.label}}<span v-if="item.id==='plan'">{{draft.cases.length}}</span><span v-if="item.id==='sessions'">{{sessions.length}}</span></button><span class="tp-save-state"><span :class="{dirty}"></span>{{writingLabel}}</span></nav>
        <div v-if="dirty" class="tp-draft-bar"><span>{{staleDrafts[current.id]?'The saved plan changed. Reload it or explicitly keep your draft before saving.':writingRecovered[current.id]?'Recovered your unfinished writing. Save plan when this is ready to become a checkpoint.':'Draft recovery is automatic. Save plan to use these changes in new sessions and reports.'}}<small class="tp-writing-status" role="status">{{writingLabel}}</small></span><div><button v-if="staleDrafts[current.id]" type="button" class="tp-link" :disabled="!!pending" @click="keepPlanDraft">Keep my draft</button><button type="button" class="tp-link" :disabled="!!pending" @click="ask('discard',{title:'Discard these plan changes?',message:'Returns this package’s draft to its last saved version.',button:'Discard changes'})">Discard</button><button type="button" class="tp-primary" :disabled="!!pending" @click="savePlan">{{pending==='save'?'Saving…':'Save plan'}}</button></div></div>
        <div v-if="writingState.status==='error'||writingState.status==='conflict'" class="tp-notice tp-error" role="alert"><Icon name="signal"/><div><strong>Writing recovery needs attention</strong><p>{{writingState.error}} Your writing is still open here.</p><button type="button" :disabled="!!pending" @click="reviewWriting">Review recovery options</button></div></div>
        <section v-if="writingConflict?.id===current.id" class="tp-writing-review"><h4>Choose the writing to keep</h4><p>Review both copies. This changes the recovery draft; it does not publish a plan or alter a preserved session.</p><div class="tp-writing-review-columns"><div><h5>This window</h5><pre tabindex="0">{{JSON.stringify(writingConflict.local,null,2)}}</pre></div><div><h5>Saved recovery draft</h5><pre tabindex="0">{{JSON.stringify(writingConflict.remote.draft,null,2)}}</pre></div></div><div class="tp-actions"><button type="button" :disabled="!!pending" @click="resolveWriting(true)">Keep this window’s writing</button><button type="button" :disabled="!!pending" @click="resolveWriting(false)">Recover saved writing</button><button type="button" class="tp-link" @click="writingConflict=null">Cancel</button></div></section>
        <details v-if="heldObservations[current.id]?.length" class="tp-writing-review"><summary>{{heldObservations[current.id].length}} recovered observations need review</summary><p>Their original session or saved observation changed. These copies stay separate so preserved results are not overwritten.</p><div v-for="item in heldObservations[current.id]" :key="item.sessionId+'/'+item.caseId"><strong>{{sessions.find(session=>session.id===item.sessionId)?.name||'Removed session'}} · {{sessions.find(session=>session.id===item.sessionId)?.cases.find(c=>c.id===item.caseId)?.title||'Removed case'}}</strong><p>{{item.reason}}</p><pre tabindex="0">{{item.notes}}</pre><template v-if="recoverableObservation(item)"><details><summary>Compare the saved observation</summary><pre tabindex="0">{{sessions.find(session=>session.id===item.sessionId)?.results.find(result=>result.caseId===item.caseId)?.notes||'No saved observation'}}</pre></details><button type="button" :disabled="!!pending" @click="useRecoveredObservation(item)">Use this recovered text</button></template></div><button type="button" class="tp-danger-link" :disabled="!!pending" @click="ask('discard-recovery',{title:'Discard recovered observations?',message:'Removes these separate recovery copies. Saved session results stay unchanged.',button:'Discard recovery copies'})">Discard recovery copies…</button></details>
        <div v-if="confirmation" class="tp-confirm-wrap"><Confirm :key="confirmation.action+confirmation.sourceId+confirmation.caseId+confirmation.sessionId" :title="confirmation.title" :message="confirmation.message" :busy="!!pending" :button-label="confirmation.button" @confirm="confirmAction" @cancel="confirmation=null"/></div>
        <div v-if="view==='overview'" class="tp-overview tp-content"><div class="tp-overview-main"><span class="tp-eyebrow">THE QUESTION & THE CONTEXT</span><label class="tp-name-label">Package name<input v-model="draft.title" maxlength="200" :disabled="!!pending"/></label><div class="tp-two-fields"><label>QA status<select v-model="draft.status" :disabled="!!pending"><option v-for="status in PACKAGE_STATUSES" :key="status.id" :value="status.id">{{status.label}}</option></select></label><label>GitHub issue<input v-model="draft.issueUrl" @input="draft.issueTitle=''" type="url" placeholder="https://github.com/…" :disabled="!!pending"/></label></div><div class="tp-two-fields"><label>Fix pull request <span>optional</span><input id="testPackageFix" v-model="draft.fixUrl" @input="draft.fixTitle=''" type="url" placeholder="https://github.com/…/pull/…" :disabled="!!pending"/></label><label>Fix label <span>optional</span><input v-model="draft.fixTitle" maxlength="500" placeholder="What the change is meant to do" :disabled="!!pending"/></label></div><div class="tp-fix-tools"><button type="button" class="tp-link" :disabled="!!pending||!pullRequestReference(draft.fixUrl)" @click="lookupFix('overview')"><Icon name="search"/>{{pending==='fix-lookup'?'Looking up…':'Look up on GitHub'}}</button><span class="tp-hint">An explicit read of the pull request through your Test Lab GitHub connection. Nothing is saved until you save the plan.</span></div><p v-if="fixLookupError.overview" class="tp-notice tp-error" role="alert"><Icon name="signal"/><span>{{fixLookupError.overview}}</span><button v-if="fixLookupNeedsConnection(fixLookupError.overview)" type="button" class="tp-link" @click="connectGitHub">Manage GitHub connection</button></p><div v-if="fixLookup.overview" class="tp-fix-readout"><Icon name="branch"/><div><strong>{{fixLookup.overview.label}}</strong><p>{{fixLookupState(fixLookup.overview)}} · {{fixLookup.overview.headRef}} → {{fixLookup.overview.baseRef}} · head {{fixLookup.overview.headSha.slice(0,10)}}<span v-if="fixLookup.overview.mergeSha"> · merged as {{fixLookup.overview.mergeSha.slice(0,10)}}</span></p><p v-if="fixLookup.overview.issues.length" class="tp-fix-issues">Closes <button v-for="issue in fixLookup.overview.issues" :key="issue" type="button" class="tp-link" :disabled="!!pending||draft.issueUrl===issue" @click="useLookupIssue(issue)">{{issue.split('/').slice(-3).join('/')}}{{draft.issueUrl===issue?' · linked':''}}</button></p><div class="tp-fix-readout-actions"><button v-if="draft.fixTitle!==fixLookup.overview.label" type="button" class="tp-link" :disabled="!!pending" @click="draft.fixTitle=fixLookup.overview.label">Use as fix label</button><small>Fetched {{packageDate(fixLookup.overview.fetchedAt,true)}}. Pull request state can change later; only the label and links you save are kept.</small></div></div></div><label>Investigation brief<textarea v-model="draft.summary" rows="6" placeholder="What’s happening? What should happen? What needs to be verified?" :disabled="!!pending"/></label><div class="tp-notes-heading"><label for="testPackageNotes">Working notes</label><span><Icon name="lock"/>Private by default</span></div><textarea id="testPackageNotes" v-model="draft.notes" rows="7" placeholder="Developer conversations, questions, observations, links, and the next thing to try…" :disabled="!!pending"/><p class="tp-hint">Notes stay out of reports and exports unless you explicitly include them. Keep passwords and tokens out of the package.</p><button type="button" class="tp-primary" :disabled="!!pending||!dirty" @click="savePlan"><Icon name="check"/>Save plan</button></div><aside class="tp-overview-aside"><div v-if="journey" class="tp-journey" aria-label="Investigation progress"><span class="tp-eyebrow">WHERE THIS STANDS</span><ol><li v-for="stage in journey.stages" :key="stage.id" :data-state="stage.state"><span class="tp-journey-dot" aria-hidden="true"></span><span><strong>{{stage.label}}<em>{{JOURNEY_STATE_LABELS[stage.state]}}</em></strong><small>{{stage.detail}}</small></span></li></ol><p>{{journey.next}}</p><button type="button" class="tp-link" :disabled="!!pending" @click="followJourney">{{journeyLabel}}<Icon name="arrow"/></button><small class="tp-journey-note">Derived from saved sessions. Package status and case outcomes stay yours to set.</small></div><div class="tp-session-glance"><h4>Latest sessions</h4><p v-if="!sessions.length" class="tp-hint">No recorded attempts yet.</p><button v-for="item in sessions.slice(0,4)" :key="item.id" type="button" :disabled="!!pending" @click="chooseSession(item.id);view='sessions'"><span class="tp-session-dot" :data-state="item.status"></span><span><strong>{{item.name}}</strong><small>{{item.status==='active'?'In progress':formatFinding(item.finding)}} · {{packageDate(item.startedAt)}}</small></span><Icon name="arrow"/></button></div><div class="tp-delete-package"><button type="button" class="tp-danger-link" :disabled="!!pending" @click="ask('delete',{title:'Delete this local test package?',message:'Deletes this package, its sessions, and package-owned evidence from this computer. Lab source records and any GitHub backup stay in place.',button:'Delete local package'})"><Icon name="trash"/>Delete package…</button></div></aside></div>
        <div v-else-if="view==='plan'" class="tp-plan"><aside class="tp-case-nav"><header><span class="tp-eyebrow">MANUAL CASES</span><button type="button" class="tp-icon-button" title="Add a case" aria-label="Add a case" :disabled="!!pending" @click="addCase"><Icon name="plus"/></button></header><button v-for="(item,index) in draft.cases" :key="item.id" type="button" class="tp-case-item" :class="{selected:selectedCaseId===item.id}" :disabled="!!pending" @click="selectedCaseId=item.id"><span>{{String(index+1).padStart(2,'0')}}</span><span><strong>{{item.title||'Untitled case'}}</strong><small>{{item.steps.length}} steps · {{item.automation==='planned'?'Automation planned':item.automation==='automated'?'Automated coverage':'Manual'}}</small></span></button><button type="button" class="tp-link" :disabled="!!pending" @click="addCase"><Icon name="plus"/>Add a test case</button></aside><div class="tp-case-canvas"><CaseEditor v-if="selectedCase" :key="selectedCase.id" :model-value="selectedCase" :number="draft.cases.findIndex(item=>item.id===selectedCase.id)+1" :disabled="!!pending" @update:model-value="updateCase" @remove="ask('remove-case',{title:'Remove this case from the plan?',message:'Removes the case from your current draft. Earlier sessions retain their frozen copy. Save the plan to keep this change.',button:'Remove case'})"/><div v-else class="tp-empty"><Icon name="file"/><h4>A repeatable plan starts here.</h4><p>Add manual cases now. Link automated coverage as it becomes available.</p><button type="button" class="tp-primary" :disabled="!!pending" @click="addCase"><Icon name="plus"/>Write a test case</button></div></div></div>
        <div v-else-if="view==='sessions'" class="tp-sessions tp-content">
          <form v-if="startOpen" id="package-session-start" class="tp-start" @submit.prevent="startSession"><div class="tp-section-heading"><div><span class="tp-eyebrow">{{startBaseline?'BASELINE → CANDIDATE':'A NEW CHECKPOINT'}}</span><h4>{{startBaseline?'Test the fix. Keep the comparison.':'Record an attempt.'}}</h4><p>{{startBaseline?'Repeat the baseline’s exact cases against your candidate. Results and step markers start fresh.':'Your saved plan becomes a preserved copy in this session.'}}</p></div><button type="button" class="tp-icon-button" aria-label="Cancel new session" :disabled="!!pending" @click="startOpen=false"><Icon name="close"/></button></div><div v-if="startBaseline" class="tp-baseline-brief"><Icon name="lock"/><div><span class="tp-eyebrow">PRESERVED BASELINE</span><strong>{{startBaseline.name}}</strong><p>{{startBaseline.environment?.rancherVersion||'Rancher version not recorded'}} · {{startBaseline.cases.length}} frozen cases · {{formatFinding(startBaseline.finding)}}</p><small>The comparison keeps a copy of this baseline. Later plan edits or deletion of the original session won’t change it.</small></div></div><div class="tp-two-fields"><label>Session name<input v-model="startDraft.name" maxlength="200" required :disabled="!!pending"/></label><label>Purpose<select v-model="startDraft.purpose" :disabled="!!pending||!!startBaseline"><option value="reproduction">Reproduce the original issue</option><option value="validation">Validate the fix</option><option value="exploration">Explore behavior</option></select></label></div><template v-if="startDraft.purpose==='validation'||startBaseline"><div class="tp-two-fields"><label>Fix under test <span>optional</span><input v-model="startDraft.fixUrl" type="url" placeholder="https://github.com/…/pull/…" :disabled="!!pending" @input="startDraft.fixTitle='';startDraft.fixCommit='';fixLookup.start=null;fixLookupError.start=''"/></label><label>Commit under test <span>optional</span><input v-model="startDraft.fixCommit" maxlength="40" pattern="[0-9a-fA-F]{7,40}" placeholder="Head commit SHA, filled by the lookup" :disabled="!!pending||!startDraft.fixUrl.trim()"/></label></div><div class="tp-fix-tools"><button type="button" class="tp-link" :disabled="!!pending||!pullRequestReference(startDraft.fixUrl)" @click="lookupFix('start')"><Icon name="search"/>{{pending==='fix-lookup'?'Looking up…':'Look up the current head commit'}}</button><span class="tp-hint">Recorded with this session as the fix it tested. Changing the package’s fix link later does not rewrite it.</span></div><p v-if="fixLookupError.start" class="tp-notice tp-error" role="alert"><Icon name="signal"/><span>{{fixLookupError.start}}</span><button v-if="fixLookupNeedsConnection(fixLookupError.start)" type="button" class="tp-link" @click="connectGitHub">Manage GitHub connection</button></p><div v-if="fixLookup.start" class="tp-fix-readout"><Icon name="branch"/><div><strong>{{fixLookup.start.label}}</strong><p>{{fixLookupState(fixLookup.start)}} · {{fixLookup.start.headRef}} → {{fixLookup.start.baseRef}} · head {{fixLookup.start.headSha.slice(0,10)}}<span v-if="fixLookup.start.mergeSha"> · merged as {{fixLookup.start.mergeSha.slice(0,10)}}</span></p><div class="tp-fix-readout-actions"><button v-if="fixLookup.start.mergeSha&&startDraft.fixCommit!==fixLookup.start.mergeSha" type="button" class="tp-link" :disabled="!!pending" @click="startDraft.fixCommit=fixLookup.start.mergeSha">Use the merge commit instead</button><button v-if="startDraft.fixCommit!==fixLookup.start.headSha" type="button" class="tp-link" :disabled="!!pending" @click="startDraft.fixCommit=fixLookup.start.headSha">Use the head commit</button><small>Fetched {{packageDate(fixLookup.start.fetchedAt,true)}}. Confirm the candidate build actually contains this commit; Runway does not verify that.</small></div></div></div></template><label>{{startBaseline?'Candidate environment':'Environment'}}<select v-model="startDraft.clusterId" :disabled="!!pending"><option value="">Describe an environment manually</option><option v-for="cluster in clusterWorkspaces" :key="cluster.id" :value="cluster.id">{{clusterDisplayName(cluster.id)}} · {{cluster.version||'version not recorded'}}{{cluster.archived?' · retained history':''}}</option></select></label><div v-if="startDraft.clusterId" class="tp-environment-preview"><p v-if="environmentLoading&&!environmentPreview" class="tp-info" role="status"><Icon name="clock"/>Loading the recorded environment…</p><p v-if="environmentError" class="tp-notice tp-error" role="alert">{{environmentError}}<button type="button" class="tp-link" :disabled="!!pending" @click="previewEnvironment()">Retry</button></p><Environment v-if="environmentPreview" :environment="environmentPreview" :name="clusterDisplayName(startDraft.clusterId)" preview :busy="environmentLoading||!!pending" @refresh="previewEnvironment(true)"/></div><div v-else><label>Rancher URL <span>optional</span><input v-model="startDraft.url" type="url" placeholder="https://rancher.example.com" :disabled="!!pending"/></label><div class="tp-two-fields"><label>Rancher version<input v-model="startDraft.rancherVersion" placeholder="e.g. v2.15.2" :disabled="!!pending"/></label><label>Kubernetes version<input v-model="startDraft.kubernetesVersion" placeholder="Exact version, if known" :disabled="!!pending"/></label></div></div><details class="tp-details"><summary>Additional environment details</summary><label v-if="startDraft.clusterId">Kubernetes version <span>manually recorded, optional</span><input v-model="startDraft.kubernetesVersion" placeholder="Exact version, if known" :disabled="!!pending"/></label><label>Images & digests <span>one per line</span><textarea v-model="startDraft.images" rows="3" placeholder="rancher/rancher@sha256:…" :disabled="!!pending"/></label><label>Configuration & prerequisites<textarea v-model="startDraft.configuration" rows="3" placeholder="Topology, relevant flags, account roles, fixtures. No credentials." :disabled="!!pending"/></label></details><div class="tp-info"><Icon name="clock"/><p>Steps create manual time markers. No tests run or logs stream automatically. Attach lab evidence or take a Rancher / webhook log snapshot as you work.</p></div><div class="tp-actions"><button type="submit" class="tp-primary" :disabled="!!pending||environmentLoading||!startDraft.name.trim()"><Icon name="play"/>{{pending==='start'?'Starting…':'Start recording steps'}}</button><button type="button" :disabled="!!pending" @click="startOpen=false">Cancel</button></div></form>
          <template v-else><div v-if="sessions.length" class="tp-session-selector"><label>Session<select :value="selectedSessionId" :disabled="!!pending" @change="chooseSession($event.target.value)"><option v-for="item in sessions" :key="item.id" :value="item.id">{{item.name}} · {{item.status==='active'?'In progress':formatFinding(item.finding)}}</option></select></label><button type="button" :disabled="!!pending||dirty||!current.cases.length" @click="prepareSession"><Icon name="plus"/>New session</button></div><div v-if="!session" class="tp-empty"><Icon name="clock"/><h4>Keep each attempt intact.</h4><p>Reproduce the issue in one session. Validate the candidate in another. Each keeps the plan and environment it started with.</p><button type="button" class="tp-primary" :disabled="!!pending||dirty||!current.cases.length" @click="prepareSession"><Icon name="play"/>Start the first session</button><small v-if="!current.cases.length">Add and save a case in the Test plan first.</small></div>
          <template v-else><div class="tp-session-header"><div><span class="tp-eyebrow">{{nicePurpose(session.purpose)}}<span class="tp-status" :data-status="session.status">{{session.status==='active'?'In progress':'Preserved'}}</span></span><h4>{{session.name}}</h4><p>{{packageDate(session.startedAt,true)}}<span v-if="session.status==='completed'&&packageDate(session.finishedAt)!=='Not recorded'"> → {{packageDate(session.finishedAt,true)}}</span></p><button v-if="session.fixUrl" type="button" class="tp-link tp-issue tp-fix" @click="openURL(session.fixUrl)"><Icon name="branch"/>Fix under test: {{session.fixTitle||session.fixUrl}}<span v-if="session.fixCommit"> · commit {{session.fixCommit.slice(0,10)}}</span><Icon name="external"/></button></div><button v-if="session.status==='active'" type="button" class="tp-primary" :disabled="!!pending" @click="prepareFinish"><Icon name="check"/>Finish session</button><div v-else class="tp-preserved-actions"><div class="tp-finding" :data-finding="session.finding"><Icon :name="session.finding==='validated'?'check':'bookmark'"/>{{formatFinding(session.finding)}}</div><button type="button" class="tp-primary" :disabled="!!pending||!session.cases.length" @click="prepareValidation(session)"><Icon name="layers"/>Validate against this baseline</button></div></div>
            <Environment :environment="session.environment" :name="displayEnvironment(session.environment)" @open-cluster="openClusterWorkspace"/>
            <div v-if="finishOpen" class="tp-finish"><h4>Preserve this checkpoint</h4><p>Finishing locks this session’s cases, results, and evidence. Unrun cases remain unrun. You can start another session at any time.</p><div class="tp-two-fields"><label>Finding<select v-model="finishDraft.finding" :disabled="!!pending"><option v-for="finding in findingOptions" :key="finding.id" :value="finding.id">{{finding.label}}</option></select></label><div class="tp-finish-progress"><strong>{{progress.complete}} / {{progress.total}}</strong><span>cases have an outcome</span></div></div><label>Conclusion<textarea v-model="finishDraft.conclusion" rows="4" placeholder="What did this establish? What remains uncertain or untested?" :disabled="!!pending"/></label><div class="tp-actions"><button type="button" class="tp-primary" :disabled="!!pending" @click="finishSession">{{pending==='finish'?'Preserving…':'Finish & preserve'}}</button><button type="button" :disabled="!!pending" @click="finishOpen=false">Keep working</button></div></div>
            <div v-if="session.conclusion" class="tp-conclusion"><span class="tp-eyebrow">THE FINDING</span><p>{{session.conclusion}}</p></div>
            <div class="tp-result-stats"><span><strong>{{progress.passed}}</strong> passed</span><span><strong>{{progress.failed}}</strong> failed</span><span><strong>{{progress.blocked}}</strong> blocked</span><span><strong>{{progress.total-progress.complete}}</strong> not run</span><span class="tp-stats-note">Checking steps does not mark a case passed.</span></div>
            <Execution id="package-execution" tabindex="-1" :session="session" :case-id="sessionCaseId" :observation="observation" :observation-blocked="observationBlocked" :busy="!!pending" @select-case="selectExecutionCase" @update:observation="observation=$event" @mark-step="markStep($event.step,$event.done)" @outcome="outcome" @save-observation="saveObservation" @logs="prepareLogCapture($event.caseId,$event.stepId)" @attach-evidence="evidenceForCase" @run-automation="runCaseAutomation"/>
            <Comparison v-if="session.baseline" :session="session" :busy="!!pending" @select-case="selectExecutionCase"/>
            <section class="tp-evidence"><header><div><span class="tp-eyebrow">THE EVIDENCE</span><h4>Keep the finding connected.</h4><p>Keep a point-in-time record of what happened. Copied evidence stays with this package.</p></div><div v-if="session.status==='active'" class="tp-evidence-actions"><button v-if="session.environment?.clusterId" type="button" :disabled="!!pending" @click="prepareLogCapture()"><Icon name="terminal"/>Get log snapshot</button><button type="button" :disabled="!!pending" @click="prepareEvidence"><Icon name="plus"/>Attach evidence</button></div></header>
              <LogCapture v-if="logCaptureOpen" id="package-log-capture" :key="`${current.id}/${session.id}/${logCaseId}/${logStepId}`" :pkg="current" :session="session" :request="request" :busy="!!pending" :case-id="logCaseId" :step-id="logStepId" @capture="captureLogs" @close="logCaptureOpen=false"/>
              <form v-if="evidenceOpen" id="package-evidence-form" class="tp-evidence-form" @submit.prevent="attachEvidence"><div class="tp-two-fields"><label>Evidence type<select v-model="evidenceDraft.kind" :disabled="!!pending"><option value="test-run">Test Lab result</option><option value="cache-snapshot">Cache Lab snapshot</option><option value="note">Written observation</option></select></label><label>Attach to<select v-model="evidenceDraft.caseId" :disabled="!!pending"><option value="">Entire session</option><option v-for="item in session.cases" :key="item.id" :value="item.id">{{item.title}}</option></select></label></div><label v-if="evidenceDraft.caseId">Step <span>optional</span><select v-model="evidenceDraft.stepId" :disabled="!!pending"><option value="">Entire case</option><option v-for="(step,index) in session.cases.find(item=>item.id===evidenceDraft.caseId)?.steps||[]" :key="step.id" :value="step.id">Step {{index+1}} · {{step.instruction.slice(0,100)}}</option></select></label><template v-if="evidenceDraft.kind!=='note'"><button type="button" class="tp-link" :disabled="!!pending" @click="refreshEvidence"><Icon name="refresh"/>Refresh saved lab evidence</button><label>Saved lab evidence<select v-model="sourceKey" :disabled="!!pending" required><option value="">Choose a saved record…</option><option v-for="source in evidenceSources" :key="source.key" :value="source.key">{{source.name}} · {{source.hint}}</option></select></label><p v-if="!evidenceSources.length" class="tp-hint">No eligible saved {{evidenceDraft.kind==='test-run'?'results':'snapshots'}}{{session.environment?.clusterId?' for this cluster':''}}. Finish a lab run or capture a snapshot, then refresh the saved evidence list.</p><label v-if="evidenceDraft.kind==='cache-snapshot'" class="tp-check"><input v-model="evidenceDraft.includeDatabase" type="checkbox" :disabled="!!pending"/><span>Copy the SQLite database into this package <small>Optional, up to 32 MiB. Otherwise, only snapshot metadata is preserved.</small></span></label></template><label v-else>Evidence name<input v-model="evidenceDraft.name" :disabled="!!pending" required maxlength="500" placeholder="Observed project visibility"/></label><label>What does this evidence show?<textarea v-model="evidenceDraft.description" :disabled="!!pending" rows="3" placeholder="Explain why this result or snapshot matters to the investigation."/></label><div class="tp-actions"><button type="submit" class="tp-primary" :disabled="!!pending||(evidenceDraft.kind!=='note'&&!sourceKey)||(evidenceDraft.kind==='note'&&(!evidenceDraft.name.trim()||!evidenceDraft.description.trim()))">{{pending==='evidence'?'Attaching…':'Attach to session'}}</button><button type="button" :disabled="!!pending" @click="evidenceOpen=false">Cancel</button></div></form>
              <p v-if="!sessionEvidence.length&&!evidenceOpen&&!logCaptureOpen" class="tp-evidence-empty">No evidence attached yet. Step timestamps are markers, not a recording of cluster activity.</p><div v-for="item in sessionEvidence" :key="item.id" class="tp-evidence-row"><Icon :name="item.kind==='cache-snapshot'?'database':item.kind==='test-run'?'flask':item.kind==='pod-logs'?'terminal':'file'"/><div><strong>{{item.name||'Written observation'}}</strong><p>{{item.description}}</p><p v-if="item.kind==='test-run'" class="tp-log-provenance"><span>Test Lab · {{item.metadata?.status||'Status not recorded'}} · {{item.metadata?.results?.length||0}} test events</span><span>rancher/tests@{{item.metadata?.sha||'Source not recorded'}}</span></p><p v-if="item.kind==='pod-logs'" class="tp-log-provenance"><span>{{item.metadata?.component==='webhook'?'Webhook':'Rancher'}} · {{item.metadata?.pod}} / {{item.metadata?.container}}</span><span>Captured {{packageDate(item.capturedAt,true)}}{{item.metadata?.previous?' · previous container':''}}{{item.metadata?.truncated?' · size limit reached':''}}</span></p><small>{{packageDate(item.attachedAt,true)}} · {{item.artifact&&!item.artifact.omitted?`${packageBytes(item.artifact.bytes)} copied`:item.artifact?.omitted?'File omitted from imported bundle':'Metadata / observation'}}<span v-if="item.caseId"> · {{session.cases.find(c=>c.id===item.caseId)?.title||'Case reference'}}<template v-if="item.stepId"> · Step {{(session.cases.find(c=>c.id===item.caseId)?.steps.findIndex(step=>step.id===item.stepId)??-1)+1}}</template></span></small><details v-if="item.metadata" class="tp-evidence-metadata"><summary>Preserved metadata</summary><pre tabindex="0">{{JSON.stringify(item.metadata,null,2)}}</pre></details><button v-if="item.artifact&&!item.artifact.omitted&&item.artifact.mediaType?.startsWith('text/')" type="button" class="tp-link" :disabled="!!pending" @click="readEvidence(item)">Read copied log</button><div v-if="evidencePreview?.id===item.id" class="tp-copied-log"><header><strong>{{evidencePreview.name}}</strong><button type="button" class="tp-icon-button" aria-label="Close copied log" @click="evidencePreview=null"><Icon name="close"/></button></header><p v-if="evidencePreview.truncated" class="tp-hint">Showing the first 400,000 characters. Include this copied log in a portable bundle to keep the complete file.</p><pre tabindex="0">{{evidencePreview.text}}</pre></div></div><button v-if="item.kind==='test-run'" type="button" class="tp-icon-button" title="Open source Test Lab result" aria-label="Open source Test Lab result" @click="openClusterTestRun(item.sourceId)"><Icon name="external"/></button><button v-if="item.kind==='cache-snapshot'" type="button" class="tp-icon-button" title="Open source Cache Lab snapshot" aria-label="Open source Cache Lab snapshot" @click="openClusterCache(item.workspaceId,item.sourceId)"><Icon name="external"/></button><button v-if="session.status==='active'" type="button" class="tp-icon-button" title="Remove attached evidence" aria-label="Remove attached evidence" :disabled="!!pending" @click="ask('remove-evidence',{sessionId:session.id,sourceId:item.id,title:'Remove this attached evidence?',message:'Removes this evidence and its copied attachment from the package. The original lab record stays in place.',button:'Remove evidence'})"><Icon name="trash"/></button></div>
            </section>
            <details v-if="sessions.length>1" class="tp-comparison"><summary><Icon name="layers"/>Compare recorded checkpoints</summary><div class="tp-comparison-table"><table><thead><tr><th>Session</th><th>Rancher / Kubernetes</th><th>Cases</th><th>Finding</th></tr></thead><tbody><tr v-for="item in sessions" :key="item.id"><td><button type="button" class="tp-link" :disabled="!!pending" @click="chooseSession(item.id)">{{item.name}}</button><small>{{nicePurpose(item.purpose)}} · {{packageDate(item.startedAt)}}</small></td><td>{{item.environment?.rancherVersion||'Unknown'}}<small>{{item.environment?.kubernetesVersion||'Unknown'}}</small></td><td>{{sessionProgress(item.results).passed}} passed · {{sessionProgress(item.results).failed}} failed<small>{{sessionProgress(item.results).complete}} / {{item.cases.length}} have outcomes</small></td><td>{{item.status==='active'?'In progress':formatFinding(item.finding)}}</td></tr></tbody></table></div><p class="tp-hint">Each session preserves its own plan. Different cases or environment details can limit a comparison.</p></details>
            <div class="tp-session-footer"><span><Icon :name="session.status==='completed'?'lock':'clock'"/>{{session.status==='completed'?'Preserved session. Start another attempt to record new findings.':'Saved as you record steps and outcomes.'}}</span><button type="button" class="tp-danger-link" :disabled="!!pending" @click="ask('delete-session',{sessionId:session.id,title:'Delete this recorded session?',message:'Deletes this session and its package-owned evidence. The package plan and original lab records remain available.',button:'Delete session'})">Delete session…</button></div>
          </template></template>
        </div>
        <div v-else-if="view==='share'" class="tp-content"><p v-if="dirty" class="tp-info"><Icon name="signal"/>Reports and exports use the saved plan. Save your changes to include them.</p><Sharing :key="current.id" :pkg="current" @imported="imported"/></div>
